function extraCable(edges) {
  // remove each cable from the end and test if the rest is connected (independent check)
  const n = edges.length;
  for (let k = n - 1; k >= 0; k--) {
    const g = Array.from({length: n + 1}, () => []);
    edges.forEach(([a, b], i) => { if (i !== k) { g[a].push(b); g[b].push(a); } });
    const seen = new Array(n + 1).fill(false), st = [1]; seen[1] = true; let cnt = 1;
    while (st.length) { const v = st.pop(); for (const u of g[v]) if (!seen[u]) { seen[u] = true; cnt++; st.push(u); } }
    if (cnt === n) return edges[k];
  }
}
